steps.script:
TerrainManager.load_terrain_layout("take_and_hold_vs_disruption_1")
MissionManager.check_all_objectives()
var areas = 0
var feats = 0
for p in TerrainManager.terrain_features:
	if str(p.get("piece_class", "")) == "area":
		areas += 1
	else:
		feats += 1
return "%d areas / %d features" % [areas, feats]

var want = ["area-large-9", "area-medium-15"]
var centres = {}
for p in TerrainManager.terrain_features:
	var pid = str(p.get("id", ""))
	if pid in want:
		var poly = p.get("polygon", PackedVector2Array())
		var acc = Vector2.ZERO
		for v in poly:
			acc += v
		centres[pid] = acc / max(1, poly.size())
var picked = []
for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if int(u.get("owner", 0)) != 2:
		continue
	if u.get("embarked_in", null) != null and str(u.get("embarked_in", "")) != "":
		continue
	var live = false
	for m in u.get("models", []):
		if m.get("alive", true) and m.get("position") != null:
			live = true
	if live:
		picked.append(str(uid))
	if picked.size() >= 2:
		break
var moved = 0
for i in range(min(picked.size(), want.size())):
	var c = centres.get(want[i], null)
	if c == null:
		continue
	for m in GameState.state.units[picked[i]]["models"]:
		if m.get("alive", true):
			m["position"] = {"x": c.x, "y": c.y}
	moved += 1
return moved

for e in MissionManager.get_booby_trap_candidates_11e(2):
	var pc = ""
	for p in TerrainManager.terrain_features:
		if str(p.get("id", "")) == str(e["id"]):
			pc = str(p.get("piece_class", ""))
	if pc != "area":
		return false
return true

var names = []
for c in tree.root.get_node("CardActionDialog/Content").get_children():
	if str(c.name).begins_with("Check_"):
		names.append(str(c.name).replace("Check_", ""))
return names.size()

var n = 0
for c in tree.current_scene.get_node("BoardRoot/CardActionOverlay").get_children():
	if str(c.name).begins_with("Highlight_"):
		n += 1
return n

var n = 0
for c in tree.current_scene.get_node("BoardRoot/CardActionOverlay").get_children():
	if str(c.name).begins_with("Highlight_"):
		n += 1
return n

var b = tree.current_scene.get_node_or_null("BoardRoot/CardActionOverlay/Badge_area-large-9")
if b == null:
	return "MISSING"
return str(b.text)
